import copy
from strands.session.repository_session_manager import RepositorySessionManager

def test_fix_broken_tool_use():
    # Simulate messages with 2 toolUse and 0 toolResult (orphaned toolUse)
    messages = [
        {
            "role": "assistant",
            "content": [
                {"toolUse": {"toolUseId": "id1"}},
                {"toolUse": {"toolUseId": "id2"}},
            ],
        },
        {
            "role": "user",
            "content": []
        },
    ]

    mgr = RepositorySessionManager.__new__(RepositorySessionManager)  # Bypass __init__ for test

    fixed_messages = mgr._fix_broken_tool_use(copy.deepcopy(messages))

    tool_use_count = sum(
        1 for block in fixed_messages[0]["content"] if "toolUse" in block
    )
    tool_result_count = sum(
        1 for block in fixed_messages[1]["content"] if "toolResult" in block
    )

    print(f"toolUse count: {tool_use_count}")
    print(f"toolResult count: {tool_result_count}")

    assert tool_use_count == tool_result_count, "The counts of toolUse and toolResult blocks should match."

if __name__ == '__main__':
    test_fix_broken_tool_use()
EOF"}

